import React,{useState,useRef} from 'react';import {createRoot} from 'react-dom/client';
import {newCharacter,type Entry} from '../../../src/core/model';import {newAutomationState} from '../../../src/core/automation/state';
import {planSourceSpells,setSourceSpellChoices,syncSourceSpells} from '../../../src/core/automation/sourceSpells';
import {changeSpecialSpellUses} from '../../../src/core/specialSpells';
import {SourceSpellChoiceControl} from '../../../src/ui/SourceSpellControls';import {ResourceWidgets} from '../../../src/ui/ResourceWidgets';import {SourceProvider} from '../../../src/ui/SourceName';
const entry=(id:string,kind:Entry['kind'],raw:Entry['raw']={}):Entry=>({id,name:id,english:id,kind,source:'XPHB',edition:'2024',packId:'fixture',revision:'1',entries:['原创边界测试'],raw});
const entries=[entry('晨光','spell',{level:1}),entry('潮汐','spell',{level:1})];
function make(){const c=newCharacter();c.automation=newAutomationState();c.selections=[{id:'owner',entry:entry('传承','race',{additionalSpells:[{innate:{'_':{daily:{pbe:[{choose:{from:['晨光|XPHB','潮汐|XPHB'],count:2}}]}}}}]}),quantity:1,level:1,equipped:false}];const key=planSourceSpells(c,entries).choices.find(x=>x.spells)!.key;setSourceSpellChoices(c,key,['晨光|XPHB'],entries);syncSourceSpells(c,entries);changeSpecialSpellUses(c,c.selections.find(x=>x.entry.kind==='spell')!.id,0);for(let i=0;i<9;i++)c.runtime.resources['long'+i]={name:`银色黎明传承的第${i+1}项长名称资源`,max:12345,current:2345};return c;}
function App(){const [c,setC]=useState(make),[blocked,setBlocked]=useState(true),[writable,setWritable]=useState(true);const current=useRef(c);current.current=c;const choice=planSourceSpells(c,entries).choices.find(x=>x.spells)!;const edit=(fn:(c:ReturnType<typeof make>)=>void)=>{if(blocked||!writable)return;const next=structuredClone(current.current);fn(next);if(JSON.stringify(next)===JSON.stringify(current.current))return;next.revision++;current.current=next;setC(next);};return <SourceProvider><label><input aria-label="阻止事务" type="checkbox" checked={blocked} onChange={e=>setBlocked(e.target.checked)}/>阻止事务</label><label><input aria-label="允许写入" type="checkbox" checked={writable} onChange={e=>setWritable(e.target.checked)}/>允许写入</label><SourceSpellChoiceControl c={c} choice={choice} entries={entries} edit={edit} writable={writable}/><div className="resource-diy-quickbar" style={{width:286,height:140,border:'3px solid #666'}}><ResourceWidgets c={c} rows={Object.entries(c.runtime.resources).filter(([id])=>id.startsWith('long'))} editing={false} enabled={writable} gm edit={edit} manage={()=>{}}/></div><pre id="data" hidden>{JSON.stringify(c)}</pre></SourceProvider>};createRoot(document.getElementById('root')!).render(<App/>);
